import os
import json
import requests

def main():
    api_key = os.environ.get("APIDECK_API_KEY")
    app_id = os.environ.get("APIDECK_APP_ID")

    headers = {
        "Authorization": f"Bearer {api_key}",
        "x-apideck-app-id": app_id,
        "Content-Type": "application/json"
    }

    base_url = "https://unify.apideck.com"

    # List all file-storage connectors
    url = f"{base_url}/connector/connectors"
    response = requests.get(url, headers=headers)
    print(f"GET {url} status: {response.status_code}")
    if response.status_code == 200:
        data = response.json()
        file_storage_connectors = [
            c for c in data.get("data", [])
            if "file-storage" in c.get("unified_api", "") or any("file-storage" in api for api in c.get("unified_apis", []))
        ]
        for c in file_storage_connectors:
            print(f"ID: {c.get('id')}, Name: {c.get('name')}, Status: {c.get('status')}")
    else:
        print(response.text)

if __name__ == "__main__":
    main()

import os
import json
import requests

def main():
    api_key = os.environ.get("APIDECK_API_KEY")
    app_id = os.environ.get("APIDECK_APP_ID")

    headers = {
        "Authorization": f"Bearer {api_key}",
        "x-apideck-app-id": app_id,
        "Content-Type": "application/json"
    }

    base_url = "https://unify.apideck.com"

    url = f"{base_url}/connector/connectors"
    response = requests.get(url, headers=headers)
    if response.status_code == 200:
        data = response.json()
        for c in data.get("data", []):
            if c.get("id") in ["REDACTED", "onedrive"]:
                print(f"ID: {c.get('id')}, Name: {c.get('name')}, Status: {c.get('status')}")
                print(f"Unified APIs: {[api.get('id') for api in c.get('unified_apis', [])]}")
                print("-" * 40)
    else:
        print(response.text)

if __name__ == "__main__":
    main()

import os
import json
import requests

def main():
    api_key = os.environ.get("APIDECK_API_KEY")
    app_id = os.environ.get("APIDECK_APP_ID")

    headers = {
        "Authorization": f"Bearer {api_key}",
        "x-apideck-app-id": app_id,
        "Content-Type": "application/json"
    }

    base_url = "https://unify.apideck.com"

    url = f"{base_url}/connector/connectors"
    response = requests.get(url, headers=headers)
    if response.status_code == 200:
        data = response.json()
        for c in data.get("data", []):
            if "drop" in c.get("id").lower() or "drop" in c.get("name").lower():
                print(f"ID: {c.get('id')}, Name: {c.get('name')}, Status: {c.get('status')}")
                print(f"Unified APIs: {[api.get('id') for api in c.get('unified_apis', [])]}")
                print("-" * 40)
    else:
        print(response.text)

if __name__ == "__main__":
    main()

